FUNCTION_BLOCK FB
VAR_INPUT
    openBtn : BOOL;
    closeBtn : BOOL;
    openLimit : BOOL;
    closeLimit : BOOL;
    obstacle : BOOL;
END_VAR
VAR_OUTPUT
    motorUp : BOOL;
    motorDown : BOOL;
    errorFlag : BOOL;
END_VAR
VAR
    prevOpenBtn : BOOL := FALSE;
    prevCloseBtn : BOOL := FALSE;
    prevObstacle : BOOL := FALSE;
    prevMotorUp : BOOL := FALSE;
    prevMotorDown : BOOL := FALSE;
    prevErrorFlag : BOOL := FALSE;
    state : INT := 0; // 0=IDLE, 1=OPENING, 2=CLOSING, 3=FAULT
END_VAR
VAR_TEMP
    openBtnRising : BOOL;
    closeBtnRising : BOOL;
    bothButtonsRising : BOOL;
END_VAR

// 边沿计算
openBtnRising := openBtn AND NOT prevOpenBtn;
closeBtnRising := closeBtn AND NOT prevCloseBtn;
bothButtonsRising := openBtnRising AND closeBtnRising;

// 更新历史
prevOpenBtn := openBtn;
prevCloseBtn := closeBtn;
prevObstacle := obstacle;
prevMotorUp := motorUp;
prevMotorDown := motorDown;
prevErrorFlag := errorFlag;

// 初始化电机输出
motorUp := FALSE;
motorDown := FALSE;

// 优先级1：障碍检测
IF obstacle THEN
    errorFlag := TRUE;
    state := 3;
    RETURN;
END_IF

// 优先级2：故障锁存与清除
IF errorFlag THEN
    state := 3;
    IF bothButtonsRising THEN
        errorFlag := FALSE;
        state := 0;
    END_IF
    RETURN;
END_IF

// 状态机逻辑
CASE state OF
    0: // IDLE
        IF bothButtonsRising THEN
            // 清除故障
            errorFlag := FALSE;
        ELSIF openBtnRising AND NOT closeBtn AND NOT openLimit THEN
            motorUp := TRUE;
            state := 1;
        ELSIF closeBtnRising AND NOT openBtn AND NOT closeLimit THEN
            motorDown := TRUE;
            state := 2;
        END_IF
    1: // OPENING
        IF openLimit THEN
            motorUp := FALSE;
            state := 0;
        ELSE
            motorUp := TRUE;
        END_IF
    2: // CLOSING
        IF closeLimit THEN
            motorDown := FALSE;
            state := 0;
        ELSE
            motorDown := TRUE;
        END_IF
    3: // FAULT
        // 故障状态，需要手动复位
END_CASE

// 更新历史变量
prevState := state;
